// Host side of the Metal particle push (see metal_push.h and advance_p.metal).

#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

#include "metal_push.h"
#include "vpic_metal_kernels.h"  // generated by CMake from src/metal/*.metal

#include <unistd.h>
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <map>
#include <string>
#include <utility>
#include <vector>

namespace {

// Must match PushParams in advance_p.metal (8-byte members first)
struct vpic_metal_push_params {
  uint64_t np, stride, max_nm, first;
  int64_t  rangel, rangeh;
  float    qdt_2mc, cdt_dx, cdt_dy, cdt_dz, qsp, cx, cy, cz;
  int32_t  nx, ny, nz, has_neighbors;
};
static_assert(sizeof(vpic_metal_push_params) == 96, "PushParams layout changed");

// Must match SortParams in sort.metal
struct vpic_metal_sort_params {
  uint64_t np, stride;
};

[[noreturn]] void fail(const std::string& why) {
  fprintf(stderr, "VPIC Metal push: %s\n", why.c_str());
  fflush(stderr);
  abort();
}

// Unset or empty: fallback. "0", "false", "off" or "no": false. Else true.
bool env_flag(const char* name, bool fallback) {
  const char* v = getenv(name);
  if (!v || !*v) return fallback;
  for (const char* off : {"0", "false", "off", "no", "FALSE", "OFF", "NO"})
    if (strcmp(v, off) == 0) return false;
  return true;
}

struct Wrapped {
  id<MTLBuffer> buffer;
  NSUInteger    offset;
};

struct Context {
  id<MTLDevice>               device = nil;
  id<MTLCommandQueue>         queue = nil;
  id<MTLComputePipelineState> push = nil;
  id<MTLBuffer>               counters = nil;   // [0] movers, [1] overflow, [2] no neighbors
  id<MTLBuffer>               no_neighbors = nil;  // bound when VPIC has no neighbor table yet
  NSUInteger                  threads = 0;      // threads per threadgroup
  size_t                      chunk = 0;        // particles per command buffer
  bool                        profile = false;
  // Wrapped arrays, keyed by (data pointer, bytes). The arrays live for the
  // whole run, so the wrappers are made once and reused every step.
  std::map<std::pair<uintptr_t, size_t>, Wrapped> wrapped;
  // Totals for VPIC_METAL_PROFILE
  double   gpu_seconds = 0;
  uint64_t calls = 0, particles = 0;

  // Sort pipelines and their scratch buffers (grown on demand, reused)
  id<MTLComputePipelineState> sort_count = nil, scan_blocks = nil, scan_add = nil, sort_scatter = nil;
  NSUInteger scan_threads = 0;   // threadgroup size of the scan kernels
  id<MTLBuffer> sort_rank = nil, sort_counts = nil, sort_p = nil, sort_cells = nil;
  std::vector<id<MTLBuffer>> scan_sums;   // block sums, one buffer per scan level
  double   sort_gpu_seconds = 0;
  uint64_t sort_calls = 0;
};

// Grow a scratch buffer to at least bytes (contents are not kept)
void ensure(Context& c, id<MTLBuffer> __strong& buffer, size_t bytes, const char* what) {
  if (buffer != nil && buffer.length >= bytes) return;
  buffer = [c.device newBufferWithLength:std::max<size_t>(bytes, 16) options:MTLResourceStorageModePrivate];
  if (buffer == nil) fail(std::string("could not allocate ") + std::to_string(bytes) + " bytes for " + what);
}

id<MTLComputePipelineState> pipeline(id<MTLDevice> device, id<MTLLibrary> library, NSString* name) {
  NSError* error = nil;
  id<MTLFunction> fn = [library newFunctionWithName:name];
  if (fn == nil) fail(std::string("no Metal kernel named ") + name.UTF8String);
  id<MTLComputePipelineState> p = [device newComputePipelineStateWithFunction:fn error:&error];
  if (p == nil)
    fail(std::string("building the ") + name.UTF8String + " pipeline failed: " + error.localizedDescription.UTF8String);
  return p;
}

Context& context() {
  static Context c = [] {
    Context c;
    c.device = MTLCreateSystemDefaultDevice();
    if (c.device == nil) fail("no Metal GPU is available");
    // Float atomics on device memory need an Apple7 (M1) or newer GPU
    if (![c.device supportsFamily:MTLGPUFamilyApple7])
      fail(std::string("GPU ") + c.device.name.UTF8String +
           " lacks the Apple7 feature set (M1 or newer) needed for float atomics");
    c.queue = [c.device newCommandQueue];

    MTLCompileOptions* options = [MTLCompileOptions new];
    // IEEE-conformant float math, so results match the CPU push to roundoff.
    // VPIC_METAL_FAST_MATH=1 relaxes it for experiments; validate before use.
    // Precise library functions too: in Safe mode Metal still uses fast
    // versions of sqrt and friends unless told otherwise.
    const bool fast = env_flag("VPIC_METAL_FAST_MATH", false);
    options.mathMode = fast ? MTLMathModeRelaxed : MTLMathModeSafe;
    options.mathFloatingPointFunctions = fast ? MTLMathFloatingPointFunctionsFast
                                              : MTLMathFloatingPointFunctionsPrecise;
    NSError* error = nil;
    id<MTLLibrary> library =
        [c.device newLibraryWithSource:@(VPIC_METAL_SOURCE)
                               options:options
                                 error:&error];
    if (library == nil)
      fail(std::string("compiling the Metal kernels failed: ") +
           error.localizedDescription.UTF8String);
    c.push = pipeline(c.device, library, @"advance_p");
    c.sort_count = pipeline(c.device, library, @"sort_count");
    c.scan_blocks = pipeline(c.device, library, @"scan_blocks");
    c.scan_add = pipeline(c.device, library, @"scan_add");
    c.sort_scatter = pipeline(c.device, library, @"sort_scatter");
    // The scan kernels assume 32-wide SIMD groups and full threadgroups
    if (c.scan_blocks.threadExecutionWidth != 32)
      fail("the scan kernels need 32-wide SIMD groups; this GPU has " +
           std::to_string(c.scan_blocks.threadExecutionWidth));
    c.scan_threads = std::min<NSUInteger>(1024, c.scan_blocks.maxTotalThreadsPerThreadgroup) / 32 * 32;

    const NSUInteger width = c.push.threadExecutionWidth;
    c.threads = std::min<NSUInteger>(256, c.push.maxTotalThreadsPerThreadgroup);
    c.threads = std::max<NSUInteger>(width, c.threads / width * width);

    c.counters = [c.device newBufferWithLength:3 * sizeof(uint32_t)
                                       options:MTLResourceStorageModeShared];
    c.no_neighbors = [c.device newBufferWithLength:6 * sizeof(int64_t)
                                           options:MTLResourceStorageModeShared];

    // Keep each command buffer short: macOS kills GPU work that stalls the
    // display. VPIC_METAL_CHUNK overrides the particles per command buffer.
    c.chunk = size_t(1) << 24;
    if (const char* v = getenv("VPIC_METAL_CHUNK")) {
      const long long n = atoll(v);
      if (n > 0) c.chunk = size_t(n);
    }
    c.profile = env_flag("VPIC_METAL_PROFILE", false);
    if (c.profile) {
      fprintf(stderr, "[vpic-metal] %s, %lu threads per threadgroup, %zu particles per command buffer\n",
              c.device.name.UTF8String, (unsigned long)c.threads, c.chunk);
      atexit([] {
        Context& c = context();
        if (c.particles)
          fprintf(stderr, "[vpic-metal] push totals: %llu calls, %.3f s GPU, %.3f ns/particle\n",
                  (unsigned long long)c.calls, c.gpu_seconds,
                  1e9 * c.gpu_seconds / double(c.particles));
        if (c.sort_calls)
          fprintf(stderr, "[vpic-metal] sort totals: %llu calls, %.3f s GPU\n",
                  (unsigned long long)c.sort_calls, c.sort_gpu_seconds);
      });
    }
    return c;
  }();
  return c;
}

// The Metal buffer that covers [data, data + bytes), reading and writing the
// memory in place. Metal can only wrap whole pages, so the buffer spans the
// pages around the array and the array starts at an offset into it.
Wrapped wrap(Context& c, const void* data, size_t bytes, const char* what) {
  if (data == nullptr || bytes == 0) fail(std::string(what) + " is empty");
  const auto key = std::make_pair(uintptr_t(data), bytes);
  auto it = c.wrapped.find(key);
  if (it != c.wrapped.end()) return it->second;

  const uintptr_t page = uintptr_t(getpagesize());
  const uintptr_t lo = uintptr_t(data) & ~(page - 1);
  const uintptr_t hi = (uintptr_t(data) + bytes + page - 1) & ~(page - 1);
  if (hi - lo > c.device.maxBufferLength)
    fail(std::string(what) + " needs " + std::to_string(hi - lo) +
         " bytes, more than this GPU's largest buffer (" +
         std::to_string(c.device.maxBufferLength) + " bytes)");
  id<MTLBuffer> buffer = [c.device newBufferWithBytesNoCopy:reinterpret_cast<void*>(lo)
                                                     length:hi - lo
                                                    options:MTLResourceStorageModeShared
                                                deallocator:nil];
  if (buffer == nil) fail(std::string("could not wrap ") + what + " for the GPU");
  Wrapped w{buffer, NSUInteger(uintptr_t(data) - lo)};
  c.wrapped.emplace(key, w);
  return w;
}

}  // namespace

bool vpic_metal_push_enabled() { return env_flag("VPIC_METAL_PUSH", true); }

bool vpic_metal_push_check_enabled() { return env_flag("VPIC_METAL_PUSH_CHECK", false); }

size_t vpic_metal_advance_p(const vpic_metal_push_args& a) {
  if (a.np == 0) return 0;
  @autoreleasepool {
    Context& c = context();
    if (a.max_nm > UINT32_MAX) fail("the mover list is larger than its 32-bit counter");

    const Wrapped buffers[] = {
        wrap(c, a.particles, a.particle_stride * 7 * sizeof(float), "the particles"),
        wrap(c, a.particles_i, a.particle_capacity * sizeof(int), "the particle cells"),
        wrap(c, a.interpolators, a.nvoxels * 18 * sizeof(float), "the interpolators"),
        wrap(c, a.fields, a.nvoxels * 16 * sizeof(float), "the fields"),
        a.neighbors ? wrap(c, a.neighbors, a.nvoxels * 6 * sizeof(int64_t), "the neighbor table")
                    : Wrapped{c.no_neighbors, 0},
        wrap(c, a.movers, a.max_nm * 3 * sizeof(float), "the movers"),
        wrap(c, a.movers_i, a.max_nm * sizeof(size_t), "the mover indices"),
        wrap(c, a.copies, a.max_nm * 7 * sizeof(float), "the mover copies"),
        wrap(c, a.copies_i, a.max_nm * sizeof(int), "the mover copy cells"),
    };
    uint32_t* counters = static_cast<uint32_t*>(c.counters.contents);
    counters[0] = 0;
    counters[1] = 0;
    counters[2] = 0;

    vpic_metal_push_params P{};
    P.np = a.np;
    P.stride = a.particle_stride;
    P.max_nm = a.max_nm;
    P.rangel = a.rangel;
    P.rangeh = a.rangeh;
    P.qdt_2mc = a.qdt_2mc; P.cdt_dx = a.cdt_dx; P.cdt_dy = a.cdt_dy; P.cdt_dz = a.cdt_dz;
    P.qsp = a.qsp; P.cx = a.cx; P.cy = a.cy; P.cz = a.cz;
    P.nx = a.nx; P.ny = a.ny; P.nz = a.nz;
    P.has_neighbors = a.neighbors != nullptr;

    // One command buffer per chunk of particles, all queued before waiting.
    // Command buffers on one queue run in order; the mover counter carries
    // over between them.
    id<MTLCommandBuffer> last = nil;
    NSMutableArray<id<MTLCommandBuffer>>* all = [NSMutableArray array];
    for (size_t first = 0; first < a.np; first += c.chunk) {
      const size_t n = std::min(c.chunk, a.np - first);
      P.first = first;
      id<MTLCommandBuffer> cb = [c.queue commandBuffer];
      id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
      [enc setComputePipelineState:c.push];
      for (NSUInteger k = 0; k < 9; ++k)
        [enc setBuffer:buffers[k].buffer offset:buffers[k].offset atIndex:k];
      [enc setBuffer:c.counters offset:0 atIndex:9];
      [enc setBytes:&P length:sizeof(P) atIndex:10];
      [enc dispatchThreads:MTLSizeMake(n, 1, 1)
          threadsPerThreadgroup:MTLSizeMake(c.threads, 1, 1)];
      [enc endEncoding];
      [cb commit];
      [all addObject:cb];
      last = cb;
    }
    [last waitUntilCompleted];

    double gpu = 0;
    for (id<MTLCommandBuffer> cb in all) {
      if (cb.status != MTLCommandBufferStatusCompleted)
        fail(std::string("a push command buffer failed: ") +
             (cb.error ? cb.error.localizedDescription.UTF8String : "unknown error"));
      gpu += cb.GPUEndTime - cb.GPUStartTime;
    }
    if (counters[1]) fail("the mover list overflowed (max_nm too small for this species)");
    if (counters[2])
      fail("a particle left its cell before VPIC built the grid's neighbor table "
           "(advance_p called during deck initialisation?)");

    c.gpu_seconds += gpu;
    c.calls += 1;
    c.particles += a.np;
    if (c.profile)
      fprintf(stderr, "[vpic-metal] push %zu particles in %lu command buffer(s): %.3f ms GPU, %.3f ns/particle, %u movers\n",
              a.np, (unsigned long)all.count, 1e3 * gpu, 1e9 * gpu / double(a.np), counters[0]);
    return counters[0];
  }
}

bool vpic_metal_sort_enabled() { return env_flag("VPIC_METAL_SORT", true); }

bool vpic_metal_sort_check_enabled() { return env_flag("VPIC_METAL_SORT_CHECK", false); }

void vpic_metal_sort_particles(const vpic_metal_sort_args& a) {
  if (a.np == 0) return;
  if (a.np > UINT32_MAX || a.ncells > UINT32_MAX)
    fail("the GPU sort counts particles and cells with 32-bit integers");
  @autoreleasepool {
    Context& c = context();
    const Wrapped p = wrap(c, a.particles, a.particle_stride * 7 * sizeof(float), "the particles");
    const Wrapped cells = wrap(c, a.particles_i, a.particle_capacity * sizeof(int), "the particle cells");
    ensure(c, c.sort_rank, a.np * sizeof(uint32_t), "the sort ranks");
    ensure(c, c.sort_counts, a.ncells * sizeof(uint32_t), "the cell counts");
    ensure(c, c.sort_p, a.particle_stride * 7 * sizeof(float), "the sort scratch particles");
    ensure(c, c.sort_cells, a.np * sizeof(int), "the sort scratch cells");

    // Scan levels: level 0 scans the cell counts, level k+1 the block sums of level k
    const NSUInteger tg = c.scan_threads;
    std::vector<uint32_t> level_n{uint32_t(a.ncells)};
    while (level_n.back() > tg) level_n.push_back(uint32_t((level_n.back() + tg - 1) / tg));
    if (c.scan_sums.size() < level_n.size()) c.scan_sums.resize(level_n.size());
    for (size_t l = 0; l < level_n.size(); ++l) {
      const size_t blocks = (level_n[l] + tg - 1) / tg;
      ensure(c, c.scan_sums[l], blocks * sizeof(uint32_t), "the scan block sums");
    }
    auto level_data = [&](size_t l) { return l == 0 ? c.sort_counts : c.scan_sums[l - 1]; };

    const vpic_metal_sort_params S{a.np, a.particle_stride};
    id<MTLCommandBuffer> cb = [c.queue commandBuffer];

    id<MTLBlitCommandEncoder> clear = [cb blitCommandEncoder];
    [clear fillBuffer:c.sort_counts range:NSMakeRange(0, a.ncells * sizeof(uint32_t)) value:0];
    [clear endEncoding];

    // Dispatches in one (serial) compute encoder run in order, each seeing the
    // previous one's writes
    id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
    [enc setComputePipelineState:c.sort_count];
    [enc setBuffer:cells.buffer offset:cells.offset atIndex:0];
    [enc setBuffer:c.sort_counts offset:0 atIndex:1];
    [enc setBuffer:c.sort_rank offset:0 atIndex:2];
    [enc setBytes:&S length:sizeof(S) atIndex:3];
    [enc dispatchThreads:MTLSizeMake(a.np, 1, 1) threadsPerThreadgroup:MTLSizeMake(c.threads, 1, 1)];

    [enc setComputePipelineState:c.scan_blocks];
    [enc setThreadgroupMemoryLength:32 * sizeof(uint32_t) atIndex:0];
    for (size_t l = 0; l < level_n.size(); ++l) {
      const uint32_t n = level_n[l];
      [enc setBuffer:level_data(l) offset:0 atIndex:0];
      [enc setBuffer:c.scan_sums[l] offset:0 atIndex:1];
      [enc setBytes:&n length:sizeof(n) atIndex:2];
      [enc dispatchThreadgroups:MTLSizeMake((n + tg - 1) / tg, 1, 1) threadsPerThreadgroup:MTLSizeMake(tg, 1, 1)];
    }
    [enc setComputePipelineState:c.scan_add];
    for (size_t l = level_n.size() - 1; l-- > 0;) {
      const uint32_t n = level_n[l];
      [enc setBuffer:level_data(l) offset:0 atIndex:0];
      [enc setBuffer:c.scan_sums[l] offset:0 atIndex:1];
      [enc setBytes:&n length:sizeof(n) atIndex:2];
      [enc dispatchThreadgroups:MTLSizeMake((n + tg - 1) / tg, 1, 1) threadsPerThreadgroup:MTLSizeMake(tg, 1, 1)];
    }

    [enc setComputePipelineState:c.sort_scatter];
    [enc setBuffer:p.buffer offset:p.offset atIndex:0];
    [enc setBuffer:cells.buffer offset:cells.offset atIndex:1];
    [enc setBuffer:c.sort_counts offset:0 atIndex:2];
    [enc setBuffer:c.sort_rank offset:0 atIndex:3];
    [enc setBuffer:c.sort_p offset:0 atIndex:4];
    [enc setBuffer:c.sort_cells offset:0 atIndex:5];
    [enc setBytes:&S length:sizeof(S) atIndex:6];
    [enc dispatchThreads:MTLSizeMake(a.np, 1, 1) threadsPerThreadgroup:MTLSizeMake(c.threads, 1, 1)];
    [enc endEncoding];

    // Copy the sorted particles back over the originals, column by column
    id<MTLBlitCommandEncoder> back = [cb blitCommandEncoder];
    const NSUInteger column = a.particle_stride * sizeof(float);
    for (NSUInteger v = 0; v < 7; ++v)
      [back copyFromBuffer:c.sort_p sourceOffset:v * column toBuffer:p.buffer
         destinationOffset:p.offset + v * column size:a.np * sizeof(float)];
    [back copyFromBuffer:c.sort_cells sourceOffset:0 toBuffer:cells.buffer
       destinationOffset:cells.offset size:a.np * sizeof(int)];
    [back endEncoding];

    [cb commit];
    [cb waitUntilCompleted];
    if (cb.status != MTLCommandBufferStatusCompleted)
      fail(std::string("the sort command buffer failed: ") +
           (cb.error ? cb.error.localizedDescription.UTF8String : "unknown error"));
    const double gpu = cb.GPUEndTime - cb.GPUStartTime;
    c.sort_gpu_seconds += gpu;
    c.sort_calls += 1;
    if (c.profile)
      fprintf(stderr, "[vpic-metal] sort %zu particles over %zu cells: %.3f ms GPU (%zu scan levels)\n", a.np,
              a.ncells, 1e3 * gpu, level_n.size());
  }
}
